/**
 * Comment rows, soft deleted so a deleted comment keeps its place in the thread.
 *
 * Must call (do not reimplement): archivePatch, shouldFilterArchived
 */
import { and, asc, count, desc, eq, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { archivePatch, shouldFilterArchived } from "@/lib/soft-delete";
import { comments, getDb, users } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import { toComment, toUser } from "./_mappers";
import type {
  CreateCommentInput,
  ListCommentsInput,
  UpdateCommentInput,
} from "@/schemas/comment";
import type {
  Comment,
  CommentThreadNode,
  CommentWithAuthor,
} from "@/types/comment";
import type { CommentId, IssueId, OrgId, Page, UserId } from "@/types/common";

export async function findCommentById(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment | null> {
  const row = getDb()
    .select()
    .from(comments)
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .get();
  return row ? toComment(row) : null;
}

export async function listComments(
  input: ListCommentsInput,
): Promise<Page<CommentWithAuthor>> {
  const db = getDb();
  const sort = { sortColumn: comments.createdAt, idColumn: comments.id };

  const filters = compact(
    orgPredicate(comments.orgId, input.orgId),
    eq(comments.issueId, input.issueId),
    shouldFilterArchived(input) ? isNull(comments.archivedAt) : undefined,
  );

  const total = db
    .select({ value: count() })
    .from(comments)
    .where(and(...filters))
    .get();

  const rows = db
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(comments.createdAt), desc(comments.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
    (row) => ({ ...toComment(row.comment), author: toUser(row.author) }),
    (row) => ({ id: row.comment.id, sortValue: row.comment.createdAt }),
  );
}

/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by its replies. Archived comments are kept so a reply
 * chain never loses its anchor — the UI renders them as "deleted".
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const repliesBy = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = repliesBy.get(comment.parentId) ?? [];
    bucket.push(comment);
    repliesBy.set(comment.parentId, bucket);
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => ({
      comment,
      replies: repliesBy.get(comment.id) ?? [],
    }));
}

export async function countComments(
  orgId: OrgId,
  issueId: IssueId,
): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(comments)
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
        isNull(comments.archivedAt),
      ),
    )
    .get();
  return row?.value ?? 0;
}

export async function insertComment(
  input: CreateCommentInput,
  authorId: UserId,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(comments)
    .values({
      id: newId(),
      orgId: input.orgId,
      issueId: input.issueId,
      authorId,
      body: input.body,
      parentId: input.parentId,
      editedAt: null,
      mentionedUserIds: JSON.stringify(input.mentionedUserIds),
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toComment(row);
}

/** An edit stamps `edited_at`, which the UI shows next to the timestamp. */
export async function updateComment(
  input: UpdateCommentInput,
): Promise<Comment> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(comments)
    .set({ body: input.body, editedAt: stamp, updatedAt: stamp })
    .where(
      and(
        orgPredicate(comments.orgId, input.orgId),
        eq(comments.id, input.commentId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${input.commentId} not found`);
  return toComment(row);
}

export async function archiveComment(
  orgId: OrgId,
  commentId: CommentId,
): Promise<Comment> {
  const row = getDb()
    .update(comments)
    .set(archivePatch())
    .where(and(orgPredicate(comments.orgId, orgId), eq(comments.id, commentId)))
    .returning()
    .get();

  if (!row) throw new Error(`Comment ${commentId} not found`);
  return toComment(row);
}

"use server";

/**
 * Marks one notification read.
 *
 * Owner D. `notification:read` is granted to every role, but the resource
 * carries `recipientId` — the ownership escalation inside `can()` is what stops
 * one member marking another member's inbox.
 *
 * Must call (do not reimplement): markNotificationReadSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  markNotificationReadSchema,
  type MarkNotificationReadInput,
} from "@/schemas/notification";
import { markRead } from "@/server/services/notification-service";
import type { ActionResult } from "@/types/api";
import type { Notification } from "@/types/notification";

const run = withAction<typeof markNotificationReadSchema, Notification>(
  markNotificationReadSchema,
  async (raw, actor) => {
    const input = raw as MarkNotificationReadInput;

    const allowed = can(actor, "notification:read", {
      kind: "notification",
      orgId: input.orgId,
      recipientId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("notification:read");
    }

    const notification = await markRead(actor, input);
    revalidateTagged(["notifications"], CACHE_PROFILES.seconds);
    return notification;
  },
  { revalidate: ["notifications"], cacheProfile: "seconds" },
);

export async function markNotificationReadAction(
  raw: unknown,
): Promise<ActionResult<Notification>> {
  return run(raw);
}

/**
 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
 *
 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
 */
import { subscribe } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { enqueue } from "@/server/jobs/queue";
import { toIsoTimestamp } from "@/types/common";
import { registerActivityListeners } from "./activity-service";
import { registerSearchListeners } from "./search-service";
import { registerUsageListeners } from "./usage-service";
import { registerWebhookListeners } from "./webhook-service";
import type { Unsubscribe } from "@/types/event";

/**
 * Importing this module also loads `notification-service` transitively, which
 * attaches the notification fan-out on first import — that hub has no
 * `register*` entry point of its own.
 */
import "./notification-service";

const logger = createLogger("event-registry");

/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
let detach: Unsubscribe | null = null;

/**
 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
 * runs per server process, but a hot reload in dev can call it again and must
 * not double-deliver every event.
 */
export function registerEventHandlers(): void {
  if (detach !== null) return;

  const offs: Unsubscribe[] = [
    registerActivityListeners(),
    registerSearchListeners(),
    registerUsageListeners(),
    registerWebhookListeners(),
    registerDigestBridge(),
  ];

  detach = () => {
    for (const off of offs) off();
  };

  logger.info("event handlers registered", { groups: offs.length });
}

export function unregisterEventHandlers(): void {
  detach?.();
  detach = null;
}

/**
 * The one piece of wiring that belongs to no single service: turning a
 * `digest.due` event into a queued job. Keeping it here rather than inside
 * `DigestService` stops the service layer from depending on the job layer.
 */
function registerDigestBridge(): Unsubscribe {
  return subscribe("digest.due", (payload) => {
    enqueue({
      id: `digest:${payload.orgId}:${payload.recipientId}`,
      kind: "digest-email",
      runAt: toIsoTimestamp(new Date()),
      attempts: 0,
      payload: {
        orgId: payload.orgId,
        recipientId: payload.recipientId,
        windowStart: payload.windowStart,
      },
    });
  });
}

/**
 * Shared query helpers: cursor encoding, `orgId` predicate construction and the archived-row predicate every other repository composes.
 *
 * Must call (do not reimplement): shouldFilterArchived
 */
import { eq, isNull } from "drizzle-orm";
import { shouldFilterArchived } from "@/lib/soft-delete";
import type { ArchiveScope, OrgId } from "@/types/common";
import type { SQL } from "drizzle-orm";
import type { SQLiteColumn } from "drizzle-orm/sqlite-core";

const CURSOR_SEPARATOR = "|";

/**
 * Cursors are opaque to callers: base64url of `<sortValue>|<id>`. Encoding the
 * sort value alongside the id is what lets `listX` resume from a stable point
 * even when two rows share a timestamp.
 */
export function encodeCursor(id: string, sortValue: string): string {
  return Buffer.from(`${sortValue}${CURSOR_SEPARATOR}${id}`, "utf8").toString(
    "base64url",
  );
}

export function decodeCursor(
  cursor: string,
): { id: string; sortValue: string } | null {
  let decoded: string;
  try {
    decoded = Buffer.from(cursor, "base64url").toString("utf8");
  } catch {
    return null;
  }

  const separatorAt = decoded.lastIndexOf(CURSOR_SEPARATOR);
  if (separatorAt <= 0 || separatorAt === decoded.length - 1) return null;

  return {
    sortValue: decoded.slice(0, separatorAt),
    id: decoded.slice(separatorAt + 1),
  };
}

/**
 * The tenant predicate. Every repository read and write composes this — a
 * query that does not mention `org_id` is a cross-tenant leak waiting to
 * happen, so this is the only sanctioned way to express it.
 */
export function orgPredicate(column: SQLiteColumn, orgId: OrgId): SQL {
  return eq(column, orgId);
}

/**
 * The soft-delete predicate, or `undefined` when the caller explicitly asked
 * for archived rows. The `includeArchived` decision itself lives in
 * `shouldFilterArchived()` so it cannot drift per repository.
 */
export function livePredicate(
  column: SQLiteColumn,
  scope: ArchiveScope,
): SQL | undefined {
  return shouldFilterArchived(scope) ? isNull(column) : undefined;
}

